/* global self */
// Displays what the server sends. The service worker is generated by
// Workbox and had no push handler: Apple delivered each notification to
// the phone and nothing showed it. iOS also revokes the subscription of
// a site that receives pushes without showing them.
self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { body: event.data ? event.data.text() : '' };
  }
  event.waitUntil(
    self.registration.showNotification(data.title || 'Step up', {
      body: data.body || '',
      icon: 'icons/icon-192.png',
      badge: 'icons/favicon-64.png',
    }),
  );
});

// Tapping it opens the app, or brings it forward if it's already open.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windows) => {
      for (const w of windows) if ('focus' in w) return w.focus();
      return self.clients.openWindow('./');
    }),
  );
});
